import { signedDifferenceInDays } from "helpers/date_helpers"

const DAYS_IN_WEEK = 7

export function formatTime(date) {
  return formatter({ hour: "numeric", minute: "2-digit" }).format(date)  // "1:42 PM"
}

export function formatDate(date) {
  return formatter(dateOptions(date)).format(date)  // "Sep 12" or "Sep 12, 2024"
}

export function formatDateWithYear(date) {
  return formatter({ month: "short", day: "numeric", year: "numeric" }).format(date)
}

export function formatWeekdayDate(date) {
  return formatter({ weekday: "long", month: "long", day: "numeric", ...yearIfDifferent }).format(date)
}

export function formatDatetime(date) {  // "Sep 12, 1:42 PM"
  return formatter({ month: "short", day: "numeric", hour: "numeric", minute: "2-digit", ...yearIfDifferent }).format(date)
}

export function formatRelativeTime(date) {
  const days = signedDifferenceInDays(new Date(), date)

  if (days === 0) return formatTime(date)
  if (days === -1) return "yesterday"
  if (days === 1) return "tomorrow"
  if (days < 0 && days > -DAYS_IN_WEEK) return `${-days} days ago`
  if (days > 0 && days < DAYS_IN_WEEK) return `in ${days} days`
  return formatDate(date)
